NULL<br></div><div><br></div><div>The model is below</div><div><br></div><div>Thanks so much!</div><div>setwd(&quot;/Volumes/GoogleDrive/My Drive/Social profiles&quot;)<br><br><br>library(MplusAutomation)<br>library(rhdf5)#not compatible with my R version<br><br>p_f[p_f==&quot;NaN&quot;] &lt;- NA<br>class(p_f)<br><br>p_s&lt;-subset(p_f,select=-c(ID))<br><br>efa_e  &lt;- mplusObject(<br>  TITLE = &quot;TWO-LEVEL EXPLORATORY FACTOR ANALYSIS&quot;,<br>  VARIABLE =<br>&quot;usevar=<br> dEmpa_1  dEmpa_2 dEmpa_3<br> ;<br>CLUSTER=id&quot;,<br><br>  ANALYSIS =<br> &quot;type = twolevel EFA 1 2  UW 1 2  UB;<br>  estimator = MLR;&quot;,<br><br>  MODEL = &quot;&quot; ,<br><br>  PLOT = &quot;type = plot3;&quot;,<br><br>  OUTPUT = &quot;sampstat standardized residual modindices (3.84);&quot;,<br><br> usevariables = colnames(p_s),<br>  rdata = p_s)<br><br><br><br>mplusModeler(efa_e,<br>             hashfilename = FALSE,<br>             modelout = &quot;efa_e.inp&quot;,<br>             dataout = &quot;mplusdata.dat&quot;,<br>             run =   1L<br>)<br><br><br><br><br><br><br>readModels(target = &quot;~/Google Drive/My Drive/Social profiles/efa_e.out&quot;)$summaries<br><br> #readModels(target = &quot;~/Google Drive/My Drive/Social profiles/efa_e.out&quot;)$parameters<br> <br> <br> readModels(&quot;efa_e.out&quot;, what=&quot;parameters&quot;)$parameters$unstandardized<br></div>
